import type { BallotStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

export const verificationBallotsStatusBadge: Record<BallotStatus, { variant: BadgeVariants; label: string }> = {
  pending: { variant: 'default', label: 'Pending' },
  processing: { variant: 'default', label: 'Processing' },
  completed: { variant: 'success', label: 'Completed' },
  warning: { variant: 'default', label: 'Warning' },
  error: { variant: 'destructive', label: 'Error' },
  duplicate: { variant: 'default', label: 'Same Petition' },
  empty: { variant: 'default', label: 'Empty' },
};

const defaultVerificationBallotsStatusBadge: { variant: BadgeVariants; label: string } = {
  variant: 'default',
  label: '',
};

export function getVerificationBallotsStatusBadge(status: BallotStatus): { variant: BadgeVariants; label: string } {
  return (
    verificationBallotsStatusBadge[status] ?? {
      ...defaultVerificationBallotsStatusBadge,
      label: snakeCaseToCapitalizedCase(status),
    }
  );
}

export const verificationBallotsStatuses: SelectItem<BallotStatus>[] = Object.entries(
  verificationBallotsStatusBadge
).map(([value, { label }]) => ({
  value: value as BallotStatus,
  name: label,
}));
